#!/usr/bin/env python3
"""Synthetic-only OOXML stress fixture, deterministic and free of company data."""
import json, pathlib, zipfile, hashlib, argparse
from xml.etree import ElementTree as ET
p=argparse.ArgumentParser(); p.add_argument('--output',default='relaxcat-synthetic-48846.xlsx'); p.add_argument('--styles',type=int,default=48846); p.add_argument('--rows',type=int,default=12000); a=p.parse_args()
if a.styles < 2 or a.rows < 2: p.error('--styles and --rows must both be at least 2')
N=a.styles; ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'; rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships'; pkg='http://schemas.openxmlformats.org/package/2006/relationships'
def xml(x): return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+x
def relationships(entries):return xml('<Relationships xmlns="'+pkg+'">'+''.join(f'<Relationship Id="{i}" Type="{rel}/{t}" Target="{v}"/>' for i,t,v in entries)+'</Relationships>')
# Unique named styles and unique base XF identities, with repeated formatting families.
# Names and xfId identities are distinct while visual formatting repeats every 24.
def fmt(i,cell=False):
    f=i%24
    return f'<xf numFmtId="{[0,2,4,14][f%4]}" fontId="{(f//4)%2}" fillId="{2 if f%3==2 else 0}" borderId="{f%2}"'+(f' xfId="{i}"' if cell else '')+f' applyAlignment="1"><alignment horizontal="{["left","center","right"][f%3]}"/></xf>'
styles=xml(f'<styleSheet xmlns="{ns}"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF2F2F2"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left/><right/><top/><bottom style="thin"><color auto="1"/></bottom><diagonal/></border></borders>'+f'<cellStyleXfs count="{N}">'+''.join(fmt(i) for i in range(N))+'</cellStyleXfs>'+f'<cellXfs count="{N}">'+''.join(fmt(i,True) for i in range(N))+'</cellXfs>'+f'<cellStyles count="{N}"><cellStyle name="Normal" xfId="0" builtinId="0"/>'+''.join(f'<cellStyle name="SyntheticImport_{i:05d}" xfId="{i}" customBuiltin="1"/>' for i in range(1,N))+'</cellStyles><dxfs count="1"><dxf><font><color rgb="FFFF0000"/></font></dxf></dxfs><tableStyles count="0" defaultTableStyle="TableStyleMedium2" defaultPivotStyle="PivotStyleLight16"/></styleSheet>')
rows=['<row r="1" ht="22" customHeight="1"><c r="A1" s="1" t="inlineStr"><is><t>SYNTHETIC BENCHMARK ONLY</t></is></c></row>']
for r in range(2,a.rows+1):
    base=(r*7)%N; x=r%101; y=r%17+1
    cells=f'<c r="A{r}" s="{base}" t="inlineStr"><is><t>Record {r:06d}</t></is></c><c r="B{r}" s="{(base+1)%N}"><v>{x}</v></c><c r="C{r}" s="{(base+2)%N}"><v>{y}</v></c><c r="D{r}" s="{(base+3)%N}"><f>B{r}*C{r}</f><v>{x*y}</v></c><c r="E{r}" s="{(base+4)%N}"><v>{45000+r%365}</v></c>'
    rows.append(f'<row r="{r}" s="{(base+5)%N}" customFormat="1">{cells}</row>')
sheet=xml(f'<worksheet xmlns="{ns}"><dimension ref="A1:E{a.rows}"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols><col min="1" max="1" width="24" customWidth="1" style="{N-1}"/><col min="2" max="5" width="16" customWidth="1" style="{N-2}"/></cols><sheetData>'+''.join(rows)+f'</sheetData><autoFilter ref="A2:E{a.rows}"/><mergeCells count="1"><mergeCell ref="A1:E1"/></mergeCells><conditionalFormatting sqref="D2:D{a.rows}"><cfRule type="cellIs" dxfId="0" priority="1" operator="lessThan"><formula>10</formula></cfRule></conditionalFormatting><dataValidations count="1"><dataValidation type="whole" operator="between" sqref="B2:B{a.rows}"><formula1>0</formula1><formula2>1000</formula2></dataValidation></dataValidations><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>')
parts={'xl/styles.xml':styles,'xl/worksheets/sheet1.xml':sheet,'xl/workbook.xml':xml(f'<workbook xmlns="{ns}" xmlns:r="{rel}"><bookViews><workbookView/></bookViews><sheets><sheet name="Synthetic data" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="SyntheticTotal">SUM(\'Synthetic data\'!D2:D{a.rows})</definedName></definedNames><calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>'),'xl/_rels/workbook.xml.rels':relationships([('rId1','worksheet','worksheets/sheet1.xml'),('rId2','styles','styles.xml')]),'_rels/.rels':relationships([('rId1','officeDocument','xl/workbook.xml')]),'docProps/core.xml':xml('<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>Synthetic style explosion benchmark</dc:title><dc:creator>RelaxCat synthetic generator</dc:creator><dc:description>Generated test data, not a company workbook.</dc:description></cp:coreProperties>')}
parts['_rels/.rels']=parts['_rels/.rels'].replace('</Relationships>','<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>')
overrides=[('/xl/workbook.xml','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml'),('/xl/worksheets/sheet1.xml','application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml'),('/xl/styles.xml','application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml'),('/docProps/core.xml','application/vnd.openxmlformats-package.core-properties+xml')]
parts['[Content_Types].xml']=xml('<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>'+''.join(f'<Override PartName="{path}" ContentType="{typ}"/>' for path,typ in overrides)+'</Types>')
out=pathlib.Path(a.output)
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
    for path,content in parts.items():
        ET.fromstring(content); info=zipfile.ZipInfo(path,(2026,1,1,0,0,0)); info.compress_type=zipfile.ZIP_DEFLATED; z.writestr(info,content.encode(),compresslevel=6)
with zipfile.ZipFile(out) as z:
    info=z.getinfo('xl/styles.xml'); stats={'path':str(out),'named_styles':N,'base_xfs':N,'cell_xfs':N,'visual_families':24,'rows':a.rows,'formulas':a.rows-1,'xlsx_bytes':out.stat().st_size,'styles_raw_bytes':info.file_size,'styles_compressed_bytes':info.compress_size,'sha256':hashlib.sha256(out.read_bytes()).hexdigest()}
print(json.dumps(stats,indent=2));out.with_suffix('.json').write_text(json.dumps(stats,indent=2)+'\n')
